'use strict';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=v=>esc(JSON.stringify(v,null,2));
const state={boot:null,material:null,page:'Dashboard',dirty:false,scene:0,profile:'landscape',filter:'ALL',job:null,ctc:null,decisions:{},ctcIndex:0,theme:localStorage.getItem('rec-theme')||'dark'};
const pages=['Dashboard','Materials','Text / TTS','Split Text','Alignment','CTC Review','Scenes','Assets','Library','Subtitles','Audio Mix','Titles / Thumbnail','Split / Merge','Render','Workflow','Jobs','Logs','Verify','Review','Outputs','Settings'];
let csrf='', pickerCallback=null, polling=false;
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-REC-CSRF':csrf},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||r.statusText);return data;}
function notice(message,error=false){$('#notice').textContent=message;$('#notice').className=error?'warn':'';}
function safe(fn){return async(...args)=>{try{return await fn(...args);}catch(e){notice(e.message,true);}};}
function bind(sel,fn,event='click',root=document){const el=$(sel,root);if(el)el.addEventListener(event,safe(fn));}
function badge(v){return `<span class="badge">${esc(v)}</span>`;}
function info(v){return `<pre>${json(v)}</pre>`;}
function title(v,sub=''){return `<h1>${esc(v)}</h1>${sub?`<p class="muted">${esc(sub)}</p>`:''}`;}
function select(name,values,value){return `<label>${esc(name)}<select name="${esc(name)}">${values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v||'common')}</option>`).join('')}</select></label>`;}
function num(name,value,step='any'){return `<label>${esc(name)}<input name="${esc(name)}" type="number" step="${step}" value="${esc(value)}"></label>`;}
function check(name,value){return `<label>${esc(name)}<input name="${esc(name)}" type="checkbox" ${value?'checked':''}></label>`;}
function field(name,value=''){return `<label>${esc(name)}<input name="${esc(name)}" value="${esc(value)}"></label>`;}
function needMaterial(){if(!state.material){$('#page').innerHTML=title(state.page)+`<p>Alege un material din bara de sus.</p>`;return false;}return true;}
function mediaElement(a,cls=''){const url=a?.local_path_url||a?.path_url||a?.thumbnail_path_url||a?.preview_path_url;if(!url)return `<p class="muted">Preview local nedescărcat.</p>`;return a.type==='video'||/\.(mp4|webm|mkv)/i.test(url)?`<video class="${cls}" controls preload="metadata" muted src="${esc(url)}"></video>`:`<img class="${cls}" src="${esc(url)}" alt="Asset local">`;}
function trackDirty(root=$('#page')){$$('input,textarea,select',root).forEach(el=>el.addEventListener('input',()=>state.dirty=true));}
async function refreshMaterial(){if($('#material').value)state.material=await api('/api/material?id='+encodeURIComponent($('#material').value));else state.material=null;}
function allowLeave(){return !state.dirty||confirm('Există modificări nesalvate. Continui fără salvare?');}
async function navigate(page){if(!allowLeave())return;state.dirty=false;state.page=page;notice('');$$('#nav button').forEach(b=>b.classList.toggle('active',b.textContent===page));await renderPage();}
async function submit(engine,command,values={},inline={}){if(state.material && engine!=='tts' && !values.material && !['init','compile','merge','assets','verify','split-text','merge-text','image-plan','doctor','convert-narration'].includes(command[0]))values.material=state.material.id;const job=await api('/api/jobs',{engine,command,values,inline});state.job=job.id;state.dirty=false;notice(`Job ${job.id.slice(0,8)} în coadă: ${job.type}.`);return job;}
function newDest(label){return 'output/studio/'+label+'-'+new Date().toISOString().replace(/[-:.TZ]/g,'');}
function resultLinks(result){const paths=[];function walk(x){if(Array.isArray(x))return x.forEach(walk);if(x&&typeof x==='object')return Object.values(x).forEach(walk);if(typeof x==='string'&&/\.(mp4|png|wav|mp3|srt|ass|md|json)$/.test(x)&&!x.startsWith('http'))paths.push(x);}walk(result);return [...new Set(paths)].map(p=>`<a target="_blank" rel="noopener" href="/files?path=${encodeURIComponent(p)}">${esc(p)}</a>`).join('<br>');}

// Every backend CLI option remains discoverable without duplicating its contract.
function commandPanel(container,commands,engine='media'){
 const specs=state.boot.catalog.filter(s=>s.engine===engine&&commands.includes(s.command.join(' ')));
 container.innerHTML=`<div class="row"><label>Operație backend<select class="operation">${specs.map(s=>`<option value="${esc(s.command.join(' '))}">${esc(s.command.join(' '))}${s.available?'':' (CLI explicit)'}</option>`).join('')}</select></label></div><form class="commandform"></form><div class="commandresult"></div>`;
 const form=$('form',container);const chooser=$('.operation',container);
 function draw(){const spec=specs.find(s=>s.command.join(' ')===chooser.value);if(!spec)return;form.innerHTML='';if(!spec.available){form.innerHTML=`<p>${esc(spec.limitation)}</p>`;return;}
  for(const f of spec.fields){if(['config','report','material'].includes(f.name))continue;
   let val=f.default??'';if(f.name==='output_dir'||f.name==='output_root')val=newDest(f.name);if(f.name==='output')val=newDest('export')+(engine==='tts'?'.mp3':'');
   let content;if(f.kind==='bool')content=check(f.name,val);else if(f.choices)content=select(f.name,f.choices,val);else if(f.kind==='number')content=num(f.name,val);else content=field(f.name,Array.isArray(val)?val.join(','):val);
   const wrapper=document.createElement('div');wrapper.innerHTML=content;
   const input=$('input,select',wrapper);input.dataset.field=f.name;if(f.kind==='bool')input.type='checkbox';if(f.multiple)input.placeholder='Valori separate prin virgulă';
   if(f.kind==='path'){const b=document.createElement('button');b.type='button';b.textContent='Alege…';b.onclick=()=>openPicker(p=>{input.value=p;state.dirty=true;});wrapper.append(b);}
   form.append(wrapper);
  }
  const inlineFields=spec.fields.filter(f=>['set','validate','apply','composition','intervals','manual_ranges','metadata','filters','plan','words','videos','sequence'].includes(f.name));
  if(inlineFields.length){const d=document.createElement('details');d.className='wide';d.innerHTML=`<summary>Document JSON inline (opțional, validat în Python)</summary><label>Câmp<select name="inline_field"><option value="">Fără document inline</option>${inlineFields.map(f=>`<option>${esc(f.name)}</option>`).join('')}</select></label><textarea name="inline_json">{}</textarea>`;form.append(d);}
  const b=document.createElement('button');b.type='submit';b.className='primary';b.textContent='Execută ca job';form.append(b);trackDirty(form);
 }
 chooser.onchange=draw;draw();
 form.onsubmit=safe(async e=>{e.preventDefault();const spec=specs.find(s=>s.command.join(' ')===chooser.value),values={},inline={};if(spec.fields.some(f=>f.name==='material')){if(!state.material)throw Error('Alege material.');values.material=state.material.id;}
  for(const f of spec.fields){const el=$(`[data-field="${f.name}"]`,form);if(!el)continue;let val=el.type==='checkbox'?el.checked:el.value;if(val===''||val===false)continue;if(f.multiple)val=String(val).split(',').map(s=>s.trim()).filter(Boolean);else if(f.kind==='number')val=Number(val);values[f.name]=val;}
  const inlineName=$('[name=inline_field]',form)?.value;if(inlineName){inline[inlineName]=JSON.parse($('[name=inline_json]',form).value);delete values[inlineName];}
  const j=await submit(engine,spec.command,values,inline);const box=$('.commandresult',container);box.textContent='Job '+j.id+' · vezi Jobs / Logs pentru progres și Cancel.';
  const done=await waitJob(j.id);if(!box.isConnected)return;box.innerHTML=info(done.result||{status:done.status,diagnostic:done.log_tail})+resultLinks(done.result);
  if(done.result?.parts){const chunks=await Promise.all(done.result.parts.map(async p=>{const base=done.result.manifest.slice(0,done.result.manifest.lastIndexOf('/')+1);const response=await fetch('/files?path='+encodeURIComponent(base+p.path));return {...p,text:await response.text()};}));box.innerHTML=`<h2>Fragmente · durate estimate</h2><table><tr><th>Fragment</th><th>Text</th><th>Estimare</th><th>Status / offsets</th></tr>${chunks.map(p=>`<tr><td>${esc(p.id)}</td><td>${esc(p.text)}</td><td>${p.estimated_seconds.toFixed(2)} s</td><td>ESTIMATED · Unicode ${p.start}–${p.end} · bytes ${p.byte_start}–${p.byte_end}</td></tr>`).join('')}</table>`+box.innerHTML;}

 });
}
async function openPicker(callback,path='input'){pickerCallback=callback;$('#picker').showModal();await listPicker(path);}
async function listPicker(path){$('#pickerpath').textContent=path;const rows=await api('/api/files?path='+encodeURIComponent(path));$('#pickerlist').innerHTML=rows.map((r,i)=>`<button data-file="${i}">${r.directory?'▸':'▧'} ${esc(r.name)} ${r.size===null?'':`(${r.size} B)`}</button>`).join('');$$('[data-file]').forEach(b=>b.onclick=safe(async()=>{const r=rows[Number(b.dataset.file)];if(r.directory)return listPicker(r.path);pickerCallback(r.path);$('#picker').close();}));}

async function dashboard(){const outputs=await api('/api/outputs');const mats=state.boot.materials;$('#page').innerHTML=title('Production Studio','Proiect local · aceleași servicii Python ca ./tts și ./media')+`<div class="grid"><div class="card"><h2>Materiale</h2><div class="value">${mats.length}</div></div><div class="card"><h2>Scene pentru review</h2><div class="value">${mats.reduce((n,m)=>n+(m.pending||0),0)}</div></div><div class="card"><h2>CTC low-confidence</h2><div class="value">${mats.reduce((n,m)=>n+(m.low_confidence||0),0)}</div><small>Număr per material; derivatele pot conține aceleași unități.</small></div></div><div class="grid">${['Text / TTS','Alignment','Scenes','Assets','Subtitles','Audio Mix','Render','Review','Outputs'].map(p=>`<button class="card" data-nav="${esc(p)}">${esc(p)}</button>`).join('')}</div><div class="card"><h2>Warnings / review pending</h2><p>Tehnic, browser, vizual, audiție, editorial și CTC uman sunt statusuri separate. Muzica reală: READY_FOR_USER_AUDIO.</p><p class="warn">Backend-urile AI nu se instalează automat. CTC și render se pornesc numai explicit.</p></div><h2>Output-uri recente</h2>${outputTable(outputs.slice(0,8))}<h2>Ultimele joburi</h2><div id="recentjobs"></div>`;$$('[data-nav]').forEach(b=>b.onclick=safe(()=>navigate(b.dataset.nav)));await jobList($('#recentjobs'));}
async function materialsPage(){const mats=(await api('/api/bootstrap')).materials;$('#page').innerHTML=title('Materials')+`<table><thead><tr><th>Material</th><th>Durată / rate</th><th>Scene</th><th>Aliniere</th><th>Review</th><th>Open</th></tr></thead><tbody>${mats.map(m=>`<tr><td>${esc(m.id)}</td><td>${Number(m.duration||0).toFixed(2)} s / ${esc(m.sample_rate)}</td><td>${esc(m.scenes)}</td><td>${esc(m.alignment_status)}</td><td>${esc(m.pending)} pending</td><td><button data-open="${esc(m.id)}">Deschide</button></td></tr>`).join('')}</tbody></table><div class="row"><button id="duplicate">Duplică configurația selectată</button><button id="folder">Output folder</button></div><p class="muted">Sursele externe și cache-urile comune sunt păstrate. Ștergerea nu este expusă.</p><details><summary>Creare material din audio existent</summary><div id="initform"></div></details>${state.material?`<h2>Timeline / metadata</h2>${timeline()}<details><summary>Manifest complet</summary>${info(state.material)}</details>`:''}`;$$('[data-open]').forEach(b=>b.onclick=safe(async()=>{$('#material').value=b.dataset.open;await refreshMaterial();await materialsPage();}));commandPanel($('#initform'),['init']);bind('#duplicate',async()=>{if(!needMaterial())return;const id=prompt('ID pentru copia configurației:');if(!id)return;await api('/api/duplicate',{material:state.material.id,id});await reloadBootstrap();notice('Configurație duplicată: '+id);});bind('#folder',()=>api('/api/open-folder',{path:'output/media'}).then(r=>notice(JSON.stringify(r))));}
function timeline(){const m=state.material;if(!m)return '';return `<div class="timeline">${m.scenes.map((s,i)=>`<button data-timeline="${i}" style="flex:${s.end-s.start}" title="${esc(s.id)}">${i+1}</button>`).join('')}</div><p class="muted">${m.frames} eșantioane · ${m.sample_rate} Hz · ${(m.frames/m.sample_rate).toFixed(3)} s</p>`;}
async function textPage(){let t=state.material?await api('/api/text?id='+encodeURIComponent(state.material.id)):null;$('#page').innerHTML=title('Text / TTS','Piper ro_RO-mihai-medium · CPU · aceeași configurație ca CLI')+(t?`<div class="card"><textarea id="texteditor">${esc(t.text)}</textarea><p id="wordcount">${t.words} cuvinte · ~${t.estimated_seconds.toFixed(1)} s estimate la 150 wpm</p><p class="warn">${esc(t.warning)}</p><button id="savetext">Salvează draft separat</button><details><summary>Diff / text hash</summary><code>${esc(t.sha256)}</code><pre id="textdiff">${esc(t.diff)}</pre></details></div>`:'')+`<div id="ttsforms"></div><p>Voice/model sunt fixe în backend; nu se oferă selecții inexistente.</p><div id="ttssummary"></div>`;commandPanel($('#ttsforms'),['prepare','preview','render','verify','doctor'],'tts');if(t){bind('#texteditor',()=>{const n=$('#texteditor').value.trim().split(/\s+/u).filter(Boolean).length;$('#wordcount').textContent=`${n} cuvinte · ~${(n/150*60).toFixed(1)} s estimate`;state.dirty=true;},'input');bind('#savetext',async()=>{t=await api('/api/text',{material:state.material.id,text:$('#texteditor').value,expected:t.sha256});state.dirty=false;$('#textdiff').textContent=t.diff;notice('Draft salvat; audio/aliniere nemodificate. Pentru resinteză, alege draftul și pornește preview/render explicit.');});}}
async function splitTextPage(){$('#page').innerHTML=title('Split Text','Offseturi Unicode/octet; duratele sunt estimate, fără generare audio.')+`<div id="splittextform"></div><div id="splittextresults"></div>`;commandPanel($('#splittextform'),['split-text','merge-text','synthesize-parts']);}
async function alignmentPage(){if(!needMaterial())return;const m=state.material;$('#page').innerHTML=title('Alignment')+info({alignment:m.alignment_summary,source_audio:m.timeline,source_text_sha256:m.sources.filter(x=>x.role==='original_text'),status:m.alignment_status})+`<p class="warn">Fingerprint neschimbat: inferența nu este pornită automat. Rerun selectiv folosește indici de la zero.</p><div id="alignmentform"></div>`;commandPanel($('#alignmentform'),['align','alignment-review']);}

function sceneFormValues(form,kind){const fd=new FormData(form),visual={};for(const k of ['fit','motion','transition','subtitle_placement','overlay','title_overlay'])visual[k]=fd.get(k);for(const k of ['motion_amount','zoom'])visual[k]=Number(fd.get(k));visual.focal_point=[Number(fd.get('focal_x')),Number(fd.get('focal_y'))];visual.crop=JSON.parse(fd.get('crop'));visual.pan=JSON.parse(fd.get('pan'));if(kind==='video')visual.short_policy=fd.get('short_policy');const settings={visual,review_status:fd.get('review_status'),review_note:fd.get('review_note')};if(kind==='video'){settings.video={source_start:Number(fd.get('source_start')),source_end:fd.get('source_end')===''?null:Number(fd.get('source_end')),audio_enabled:false};}return {settings,profile:fd.get('scope')||undefined};}

async function scenePage(){if(!needMaterial())return;const m=state.material;state.scene=Math.min(state.scene,Math.max(0,m.scenes.length-1));const s=m.scenes[state.scene];if(!s){$('#page').innerHTML=title('Scenes')+'<p>Material fără scene. Creează/importă un plan.</p><div id="sceneplan"></div>';commandPanel($('#sceneplan'),['scene-plan','scenes']);return;}
 const profile=state.profile,eff=s.effective[profile],a=eff.preview_asset,v=eff.visual||{},focal=eff.focal||[.5,.5];
 $('#page').innerHTML=title('Scene Editor','Space play/pause · ←/→ scena · A approved · N needs review; numai în afara inputurilor')+`<div class="filters">${['ALL','IMAGE','VIDEO','FALLBACK','NEEDS_REVIEW','APPROVED','LICENSE_UNKNOWN'].map(f=>`<button data-filter="${f}" class="${f===state.filter?'primary':''}">${f}</button>`).join('')}</div><div class="editor"><div class="scenelist">${m.scenes.map((x,i)=>{const ea=x.effective[profile].preview_asset;const match=state.filter==='ALL'||x.kind.toUpperCase()===state.filter||x.review_status===state.filter||state.filter==='LICENSE_UNKNOWN'&&ea.license==='LICENSE_UNKNOWN';return match?`<button class="sceneitem ${i===state.scene?'primary':''}" data-scene="${i}">${ea.type!=='video'&&(ea.local_path_url||ea.path_url)?`<img src="${esc(ea.local_path_url||ea.path_url)}" alt="">`:''}${esc(x.id)}<small>${(x.start/m.sample_rate).toFixed(2)}–${(x.end/m.sample_rate).toFixed(2)} s · ${esc(x.kind)}</small><small>${esc(ea.provider||'local')} · ${esc(x.review_status||'NEEDS_REVIEW')}</small></button>`:'';}).join('')}</div><section><div class="row"><button id="landscape" class="${profile==='landscape'?'primary':''}">LANDSCAPE</button><button id="portrait" class="${profile==='portrait'?'primary':''}">PORTRAIT</button></div><div class="preview ${eff.fit==='cover'?'cover':''}" id="focalpreview">${mediaElement(a)}<span class="focal" style="left:${focal[0]*100}%;top:${focal[1]*100}%"></span></div><p>${esc(s.context||s.anchor)}</p><p class="muted">${esc(s.id)} · ${((s.end-s.start)/m.sample_rate).toFixed(3)} s · video source audio MUTED</p><div class="grid">${s.alternatives.map((c,i)=>candidateCard(c,i)).join('')}</div><div id="invalidation"></div><details><summary>Metadata / previous selection / history</summary>${info(s)}</details></section><section class="properties"><form id="sceneprops"><div class="row">${select('scope',['', 'landscape','portrait'],profile)}</div><div class="row">${select('fit',['contain','cover'],eff.fit||m.effective_config.fit)}${select('motion',['none','zoom_in','zoom_out','pan'],eff.motion||'none')}${select('transition',['cut','crossfade'],eff.transition||'cut')}</div><div class="row">${num('focal_x',focal[0])}${num('focal_y',focal[1])}${num('motion_amount',eff.motion_amount??.04)}${num('zoom',eff.zoom??1)}</div><label>crop [left,top,right,bottom]<input name="crop" value="${esc(JSON.stringify(eff.crop||[0,0,1,1]))}"></label><label>pan [x,y]<input name="pan" value="${esc(JSON.stringify(eff.pan||[.5,.5]))}"></label>${select('subtitle_placement',['bottom','top'],eff.subtitle_placement||'bottom')}${field('overlay',eff.overlay||'')}${field('title_overlay',eff.title_overlay||'')}${select('review_status',['NEEDS_REVIEW','APPROVED','PROPOSED','FALLBACK','LICENSE_UNKNOWN','REJECTED'],s.review_status||'NEEDS_REVIEW')}${field('review_note',s.review_note||'')}${eff.kind==='video'?`<h3>Video trim (seconds)</h3><div class="row">${num('source_start',eff.source_start||0)}${num('source_end',eff.source_end??'')}</div>${select('short_policy',['error','freeze','loop'],eff.short_policy||'error')}<p>Fallback / different asset: selectează candidat sau Remove.</p>`:''}<div class="row"><button class="primary" type="submit">Save</button><button type="button" id="undo">Undo</button><button type="button" id="remove">Remove / fallback</button></div></form><div class="row"><button id="replace">Replace local…</button><button id="render-scene">Render scene sample</button></div><p class="muted">Preview crop/focal generează cadre prin rendererul Python. Render scene sample generează o animație într-un material derivat nou.</p></section></div>${timeline()}<details><summary>Advanced scene service / plan / sequence / limits</summary><div id="sceneadvanced"></div></details>`;
 commandPanel($('#sceneadvanced'),['scenes','scene-plan']);
 $$('[data-scene],[data-timeline]').forEach(b=>b.onclick=safe(async()=>{if(!allowLeave())return;state.dirty=false;state.scene=Number(b.dataset.scene??b.dataset.timeline);await scenePage();}));$$('[data-filter]').forEach(b=>b.onclick=safe(async()=>{state.filter=b.dataset.filter;await scenePage();}));for(const p of ['landscape','portrait'])bind('#'+p,async()=>{if(!allowLeave())return;state.profile=p;state.dirty=false;await scenePage();});
 const form=$('#sceneprops');trackDirty(form);
 function values(){return sceneFormValues(form,eff.kind);}
 bind('#focalpreview',e=>{if(e.target.closest('video'))return;const rect=e.currentTarget.getBoundingClientRect();const x=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),y=Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height));$('[name=focal_x]',form).value=x.toFixed(4);$('[name=focal_y]',form).value=y.toFixed(4);$('.focal').style.left=x*100+'%';$('.focal').style.top=y*100+'%';state.dirty=true;});
 form.onsubmit=safe(async e=>{e.preventDefault();const {settings,profile}=values();const invalid=await api('/api/invalidation',{material:m.id,scene:s.id,profile,settings:{visual:settings.visual,video:settings.video||{}}});$('#invalidation').innerHTML=info(invalid);await submit('media',['scenes'],{material:m.id,scene:s.id,profile},{set:settings});});
 bind('#undo',()=>submit('media',['scenes'],{material:m.id,scene:s.id,restore:true}));bind('#remove',()=>submit('media',['scenes'],{material:m.id,scene:s.id,profile,remove:true}));bind('#replace',()=>openPicker(path=>submit('media',['scenes'],{material:m.id,scene:s.id,profile,replace:path})));
 bind('#render-scene',async()=>{if(!confirm('Creează fragment derivat și randează proba într-o destinație nouă?'))return;const prefix='studio-scene-'+Date.now();const j=await submit('media',['split'],{material:m.id,mode:'extract',prefix,apply:true},{intervals:[[s.start,s.end]]});await waitJob(j.id);await reloadBootstrap();const child=prefix+'-001';await submit('media',['render'],{material:child,profiles:profile,output_root:newDest('scene'),subtitles:'off'});});bindCandidates(s);
}
function candidateCard(c,i){const preview=mediaElement(c);return `<div class="card candidate"><strong>Candidate ${i+1}</strong>${preview}<p>${esc(c.provider)} · ${esc(c.creator)}<br>${esc(c.license)} · ${esc(c.width)}×${esc(c.height)} ${c.duration?esc(c.duration)+' s':''}<br>${esc(c.candidate_id||c.asset_id)}</p><button data-candidate="${i}">Select</button>${!c.asset_id?`<button data-download="${i}">Download explicit</button>`:''}</div>`;}
function bindCandidates(scene){$$('[data-candidate]').forEach(b=>b.onclick=safe(async()=>{const c=scene.alternatives[Number(b.dataset.candidate)],m=state.material;const invalid=await api('/api/invalidation',{material:m.id,scene:scene.id,profile:state.profile,candidate:c.candidate_id||c.asset_id});if(!confirm(JSON.stringify(invalid.changed)+'\nSalvezi selecția?'))return;await submit('media',['scenes'],{material:m.id,scene:scene.id,profile:state.profile,select:c.candidate_id||c.asset_id});}));$$('[data-download]').forEach(b=>b.onclick=safe(async()=>{const c=scene.alternatives[Number(b.dataset.download)];if(confirm('Descarcă explicit acest candidat de la furnizor?'))await submit('media',['assets','download'],{material:state.material.id,scene:scene.id,candidate:c.candidate_id});}));}
async function assetsPage(){if(!needMaterial())return;const s=state.material.scenes[state.scene]||state.material.scenes[0];$('#page').innerHTML=title('Assets · Alternatives','Search / Download sunt acțiuni explicite de rețea. Preview-urile sunt exclusiv locale.')+`<div class="row"><label>Scene<select id="assetscene">${state.material.scenes.map((s,i)=>`<option value="${i}" ${i===state.scene?'selected':''}>${esc(s.id)}</option>`).join('')}</select></label><button id="searchqueries">Generated query</button></div><div id="queries"></div><div class="grid">${(s?.alternatives||[]).map(candidateCard).join('')}</div><details open><summary>Search / download / export Markdown</summary><div id="assetsforms"></div></details>`;bindCandidates(s);bind('#assetscene',async()=>{state.scene=Number($('#assetscene').value);await assetsPage();},'change');bind('#searchqueries',async()=>{const j=await submit('media',['assets','queries'],{material:state.material.id,scene:s.id});const result=await waitJob(j.id);$('#queries').innerHTML=info(result.result);});commandPanel($('#assetsforms'),['assets search','assets download','assets review','assets credits','assets queries']);}
async function libraryPage(){const rows=await api('/api/library');$('#page').innerHTML=title('Local Asset Library')+`<div class="row"><input id="libraryquery" placeholder="Search / tags / provider / license"><button id="librarysearch">Caută local</button><button id="libraryimport">Import image/video</button></div><p class="muted">Audio se importă explicit prin picker/upload în Audio Mix; indexul actual al bibliotecii acceptă imagini/video.</p><div class="grid" id="librarygrid"></div><details><summary>Import cu provenance / filtre exacte</summary><div id="libraryforms"></div></details>`;function draw(list){$('#librarygrid').innerHTML=list.map((a,i)=>`<div class="card candidate">${mediaElement(a)}<p>${esc(a.type)} · ${esc(a.provider)} · ${esc(a.license)}<br>${esc(a.orientation)} · ${esc(a.width)}×${esc(a.height)} · ${esc(a.duration)} s<br>${esc(a.checksum)}</p><details><summary>Metadata / tags</summary>${info(a)}</details></div>`).join('');}draw(rows);bind('#librarysearch',async()=>draw(await api('/api/library?query='+encodeURIComponent($('#libraryquery').value))));bind('#libraryimport',()=>openPicker(path=>submit('media',['assets','import'],{path}),'assets'));commandPanel($('#libraryforms'),['assets import','assets list']);}
async function ctcPage(){if(!needMaterial())return;if(!state.material.alignment){$('#page').innerHTML=title('CTC Review')+'<p>Material fără aliniere existentă.</p>';return;}state.ctc=await api('/api/ctc?id='+encodeURIComponent(state.material.id));state.decisions={};state.ctcIndex=0;drawCTC();}
function drawCTC(){const c=state.ctc,m=state.material,threshold=m.alignment.settings?.confidence_warning??.35;const rows=c.words.map((w,i)=>({...w,index:i})).filter(w=>(w.confidence??1)<threshold||w.review);const selected=rows[state.ctcIndex];$('#page').innerHTML=title('CTC Human Review','Decizii explicite legate de alignment_key, audio hash și text hash. Nu există aprobare implicită.')+`<div class="card"><div class="row">${field('reviewer',state.reviewer||'')}<button id="ctc-export">Export JSON</button><button id="ctc-validate">Validate decisions</button><button id="ctc-apply" class="danger">Apply explicit decisions</button></div><div class="row"><button id="ctc-prev">Previous</button><button id="ctc-next">Next</button><button id="ctc-unresolved">Next unresolved</button><span>${rows.length} unități pentru review / ${c.words.length} total</span></div>${m.audio_url?`<audio id="ctc-audio" controls src="${esc(m.audio_url)}"></audio><canvas id="waveform" width="1000" height="90"></canvas><button id="loadwave">Încarcă waveform local</button>`:'<p>Timeline compus: exportă audio de review explicit prin operațiile existente înainte de playback global.</p>'}<p class="warn">Sfârșitul CTC nu este automat sfârșitul acustic al cuvântului. Confirmă prin audiție și waveform.</p></div>${selected?`<div class="card"><h2>${esc(selected.spoken)} ${badge(selected.confidence)} ${badge('index '+selected.index)}</h2><p>${esc(c.words.slice(Math.max(0,selected.index-4),selected.index+5).map(w=>w.spoken).join(' '))}</p><div class="row">${num('ctc_start',selected.start,1)}${num('ctc_end',selected.end,1)}<span>samples · ${(selected.start/c.sample_rate).toFixed(6)}–${(selected.end/c.sample_rate).toFixed(6)} s</span><button id="ctc-play">Play interval</button></div><div class="row ctc-actions">${['ACCEPT','ADJUST_START','ADJUST_END','ADJUST_BOTH','REJECT','NEEDS_REVIEW'].map(a=>`<button data-decision="${a}">${a}</button>`).join('')}</div>${field('ctc_note',state.decisions[selected.index]?.note||'')}<p>Decizie curentă: ${esc(state.decisions[selected.index]?.action||'Fără decizie')}</p></div>`:'<p>Nu există unități low-confidence.</p>'}<details><summary>Identități / normalizări</summary>${info({alignment_key:c.alignment_key,audio_sha256:c.audio_sha256,source_text_sha256:c.source_text_sha256,normalizations:c.normalizations})}</details><div class="card"><h2>Decizii în sesiune (nu sunt aplicate)</h2>${info(Object.values(state.decisions))}</div><details><summary>Import/export review existent</summary><div id="reviewforms"></div></details>`;
 commandPanel($('#reviewforms'),['alignment-review']);bind('[name=reviewer]',()=>{state.reviewer=$('[name=reviewer]').value;},'input');
 function move(n){state.reviewer=$('[name=reviewer]').value;state.ctcIndex=(state.ctcIndex+n+rows.length)%rows.length;drawCTC();}bind('#ctc-prev',()=>move(-1));bind('#ctc-next',()=>move(1));bind('#ctc-unresolved',()=>{for(let n=1;n<=rows.length;n++){const i=(state.ctcIndex+n)%rows.length;if(!state.decisions[rows[i].index]){state.ctcIndex=i;drawCTC();break;}}});
 bind('#ctc-play',()=>{const player=$('#ctc-audio');if(!player)throw Error('Playback global indisponibil pentru timeline compus.');player.currentTime=Math.max(0,selected.start/c.sample_rate-.4);player.ontimeupdate=()=>{if(player.currentTime>selected.end/c.sample_rate+.4)player.pause();};return player.play();});
 $$('[data-decision]').forEach(b=>b.onclick=safe(()=>{const action=b.dataset.decision,d={index:selected.index,action,note:$('[name=ctc_note]').value};if(['ADJUST_START','ADJUST_BOTH'].includes(action))d.start=Number($('[name=ctc_start]').value);if(['ADJUST_END','ADJUST_BOTH'].includes(action))d.end=Number($('[name=ctc_end]').value);state.reviewer=$('[name=reviewer]').value;state.decisions[selected.index]=d;state.dirty=true;drawCTC();}));
 function exported(){const reviewer=$('[name=reviewer]').value.trim();if(!reviewer)throw Error('Reviewer obligatoriu.');if(!Object.keys(state.decisions).length)throw Error('Selectează cel puțin o decizie explicită.');return {schema_version:2,material:m.id,alignment_key:c.alignment_key,audio_sha256:c.audio_sha256,source_text_sha256:c.source_text_sha256,reviewer,reviewed_utc:new Date().toISOString(),decisions:Object.values(state.decisions)};}
 bind('#ctc-export',()=>{downloadJSON(exported(),'ctc-decisions.json');state.dirty=false;});bind('#ctc-validate',()=>submit('media',['alignment-review'],{material:m.id},{validate:exported()}));bind('#ctc-apply',async()=>{const decisions=exported();if(!confirm('Aplici numai deciziile explicite, cu backup și jurnal? Operația modifică alinierea acestui material.'))return;await submit('media',['alignment-review'],{material:m.id},{apply:decisions});});
 bind('#loadwave',()=>drawWaveform(m.audio_url,$('#waveform'),$('#ctc-audio')));
}

async function drawWaveform(url,canvas,player){
 const response=await fetch(url);if(Number(response.headers.get('Content-Length'))>80_000_000)throw Error('Folosește un fragment sub 80 MB pentru waveform.');
 const raw=await response.arrayBuffer();if(raw.byteLength>80_000_000)throw Error('Audio prea mare pentru waveform în browser.');
 const context=new AudioContext();try{const buffer=await context.decodeAudioData(raw),samples=buffer.getChannelData(0),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#76d5bd';ctx.beginPath();for(let x=0;x<canvas.width;x++){const a=Math.floor(x*samples.length/canvas.width),b=Math.floor((x+1)*samples.length/canvas.width);let peak=0;for(let i=a;i<b;i++)peak=Math.max(peak,Math.abs(samples[i]));ctx.moveTo(x,45-peak*44);ctx.lineTo(x,45+peak*44);}ctx.stroke();canvas.onclick=e=>{const rect=canvas.getBoundingClientRect();player.currentTime=Math.max(0,Math.min(buffer.duration,(e.clientX-rect.left)/rect.width*buffer.duration));};}finally{await context.close();}
}

function downloadJSON(value,name){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500);}
async function subtitlesPage(){if(!needMaterial())return;const m=state.material,style=m.effective_config.subtitle_style||{};$('#page').innerHTML=title('Subtitles','Layout, ASS și preview raster sunt generate de aceleași funcții Python ca exportul real.')+`<form id="subtitleform" class="card"><div class="row">${select('mode',['classic','highlight','scroll'],'highlight')}${select('preset',['safe','boxed','minimal'],style.preset||'safe')}${select('profile',['landscape','portrait'],'landscape')}${num('preview_seconds',Math.min(2,m.frames/m.sample_rate/2))}</div><div class="row">${num('font_size',style.font_size??48,1)}${num('outline',style.outline??3)}${num('shadow',style.shadow??1)}${num('alignment',style.alignment??2,1)}${num('margin_x',style.margin_x??.06)}${num('margin_v',style.margin_v??.1)}${num('line_spacing',style.line_spacing??4)}</div><div class="row">${field('color',style.color||'FFFFFF')}${field('highlight_color',style.highlight_color||'FFD75A')}${field('safe_area',JSON.stringify(style.safe_area||[.06,.06,.06,.06]))}</div><details><summary>Stil complet / font / profile overrides (JSON)</summary><textarea id="subtitlejson">${json(style)}</textarea></details><div class="row"><button type="submit" class="primary">Save subtitle style</button><button type="button" id="subtitleundo">Undo style</button><button type="button" id="subtitlepreview">Preview frame Python</button><button type="button" id="subtitleexport">Export SRT / ASS</button></div><p class="muted">Stilul invalidează numai compoziția finală; zero scene invalidate. Preview folosește stilul salvat.</p></form><div id="subtitlepreviewresult"></div>`;const form=$('#subtitleform');trackDirty(form);
 form.onsubmit=safe(async e=>{e.preventDefault();const fd=new FormData(form),s=JSON.parse($('#subtitlejson').value);for(const k of ['font_size','outline','shadow','alignment','margin_x','margin_v','line_spacing'])s[k]=Number(fd.get(k));for(const k of ['preset','color','highlight_color'])s[k]=fd.get(k);s.safe_area=JSON.parse(fd.get('safe_area'));await api('/api/subtitle-style',{material:m.id,style:s,expected:m.manifest_sha256});state.dirty=false;await refreshMaterial();notice('Stil salvat. Scenele rămân reutilizabile; compoziția finală va fi regenerată.');});
 bind('#subtitleundo',async()=>{await api('/api/subtitle-style',{material:m.id,undo:true});state.dirty=false;await refreshMaterial();await subtitlesPage();});bind('#subtitlepreview',async()=>{const fd=new FormData(form);const j=await submit('studio',['subtitle-preview'],{material:m.id,profile:fd.get('profile'),mode:fd.get('mode'),seconds:Number(fd.get('preview_seconds'))});const result=await waitJob(j.id);if(result.status!=='complete')throw Error(result.log_tail);$('#subtitlepreviewresult').innerHTML=`<img style="max-height:600px;max-width:100%" alt="Preview ASS real" src="/files?path=${encodeURIComponent(result.result.path)}">${resultLinks(result.result)}`;});bind('#subtitleexport',()=>{const fd=new FormData(form);return submit('media',['subtitles'],{material:m.id,profiles:fd.get('profile'),mode:fd.get('mode'),ass_preset:fd.get('preset'),output_dir:newDest('subtitles')});});}
function audioRecipe(m){const r=m.audio_mix;if(!r||r.segments)return {enabled:false,tracks:[],ducking:{enabled:false,amount_db:12,attack_ms:40,release_ms:350},normalization:{enabled:true,loudness_lufs:-19,true_peak_db:-2,loudness_range:11}};return {enabled:r.enabled,tracks:r.tracks.map(t=>({type:t.type,path:t.source.path.startsWith('/')?t.source.path:`materials/${m.id}/${t.source.path}`,checksum:t.source.sha256,source:t.source.source,creator:t.source.creator,license:t.source.license,start:t.start/m.sample_rate,end:t.end/m.sample_rate,source_start:t.source_start/m.sample_rate,source_end:t.source_end/m.sample_rate,volume_db:t.volume_db,loop:t.loop,loop_fade_ms:t.loop_fade_samples/m.sample_rate*1000,fade_in:t.fade_in/m.sample_rate,fade_out:t.fade_out/m.sample_rate})),ducking:r.ducking,normalization:r.normalization};}
async function audioPage(){if(!needMaterial())return;const m=state.material;let recipe=audioRecipe(m);$('#page').innerHTML=title('Audio Mix','Master narativ imuabil · gain în dB · timpii formularului în secunde · audio asset video MUTED')+`${m.audio_mix?.segments?'<p class="warn">Mix derivat cu contexte distincte. Inspectorul păstrează contractul; o rețetă nouă îl înlocuiește numai explicit.</p>':''}<form id="audioform" class="card"><div class="row">${check('enabled',recipe.enabled)}<button type="button" id="addtrack">Add music / SFX / ambience</button></div><h2>Narration</h2><p>${m.sample_rate} Hz · mono · ${(m.frames/m.sample_rate).toFixed(3)} s · NOT_LISTENED</p>${m.audio_url?`<audio id="mixplayer" controls src="${esc(m.audio_url)}"></audio><canvas id="mixwaveform" width="1000" height="90"></canvas><button type="button" id="mixwave">Load waveform local</button>`:''}<div id="tracks"></div><h2>Ducking (music / ambience)</h2><div class="row">${check('ducking',recipe.ducking?.enabled)}${num('amount_db',recipe.ducking?.amount_db??12)}${num('attack_ms',recipe.ducking?.attack_ms??40)}${num('release_ms',recipe.ducking?.release_ms??350)}</div><h2>Normalizare finală</h2><div class="row">${check('normalize',recipe.normalization?.enabled??true)}${num('loudness_lufs',recipe.normalization?.loudness_lufs??-19)}${num('true_peak_db',recipe.normalization?.true_peak_db??-2)}${num('loudness_range',recipe.normalization?.loudness_range??11)}</div><div class="row"><button type="button" id="mixvalidate">Validate</button><button type="submit" class="primary">Save configuration</button><button type="button" id="mixrender">Render mix</button><button type="button" id="mixdisable">Disable</button><button type="button" id="mixundo">Undo config</button></div></form><details><summary>Import / inspect / verify / remux CLI services</summary><div id="mixforms"></div></details><p class="warn">Metricile LUFS/peak nu reprezintă audiție umană. Muzica reală rămâne READY_FOR_USER_AUDIO până la alegerea/aprobarea fișierului.</p>`;
 const tracks=$('#tracks');function draw(){tracks.innerHTML=recipe.tracks.map((t,i)=>`<div class="track" data-track="${i}" data-original-path="${esc(t.path)}">${select('type',['music','sfx','ambience'],t.type)}${field('path',t.path)}<button type="button" data-trackpick="${i}">File…</button>${num('volume_db',t.volume_db??0)}${num('start',t.start??0)}${num('end',t.end??m.frames/m.sample_rate)}${num('source_start',t.source_start??0)}${num('source_end',t.source_end??'')}${check('loop',t.loop)}${num('fade_in',t.fade_in??0)}${num('fade_out',t.fade_out??0)}${field('creator',t.creator||'')}${field('license',t.license||'unknown')}<input type="hidden" name="source" value="${esc(t.source||'')}"><input type="hidden" name="checksum" value="${esc(t.checksum||'')}"><input type="hidden" name="loop_fade_ms" value="${esc(t.loop_fade_ms??5)}"><button type="button" data-trackremove="${i}">Remove track</button></div>`).join('');$$('[data-trackpick]').forEach(b=>b.onclick=()=>openPicker(path=>{const input=$('[name=path]',b.closest('.track'));input.value=path;input.dispatchEvent(new Event('input',{bubbles:true}));state.dirty=true;}));$$('[data-trackremove]').forEach(b=>b.onclick=()=>{recipe=collect();recipe.tracks.splice(Number(b.dataset.trackremove),1);draw();state.dirty=true;});$$('.track',tracks).forEach(row=>$('[name=path]',row).addEventListener('input',()=>{if($('[name=path]',row).value!==row.dataset.originalPath){for(const name of ['source','checksum','creator'])$('[name='+name+']',row).value='';$('[name=license]',row).value='unknown';}}));trackDirty(tracks);}
 function collect(){const fd=new FormData($('#audioform'));return {enabled:fd.get('enabled')==='on',tracks:$$('.track',tracks).map(row=>{const t={};$$('input,select',row).forEach(el=>{if(el.value==='')return;t[el.name]=el.type==='checkbox'?el.checked:(el.type==='number'||el.name==='loop_fade_ms')?Number(el.value):el.value;});return t;}),ducking:{enabled:fd.get('ducking')==='on',amount_db:Number(fd.get('amount_db')),attack_ms:Number(fd.get('attack_ms')),release_ms:Number(fd.get('release_ms'))},normalization:{enabled:fd.get('normalize')==='on',loudness_lufs:Number(fd.get('loudness_lufs')),true_peak_db:Number(fd.get('true_peak_db')),loudness_range:Number(fd.get('loudness_range'))}};}
 bind('#mixwave',()=>drawWaveform(m.audio_url,$('#mixwaveform'),$('#mixplayer')));
 draw();trackDirty($('#audioform'));bind('#addtrack',()=>{recipe=collect();recipe.tracks.push({type:'music',path:'',volume_db:-20,start:0,end:m.frames/m.sample_rate,creator:'',license:'unknown'});draw();state.dirty=true;});$('#audioform').onsubmit=safe(async e=>{e.preventDefault();await submit('media',['audio-mix'],{material:m.id},{set:collect()});});bind('#mixvalidate',()=>submit('media',['audio-mix'],{material:m.id},{validate:collect()}));bind('#mixrender',()=>submit('media',['audio-mix'],{material:m.id,render:true,output_dir:newDest('mix')}));bind('#mixdisable',()=>submit('media',['audio-mix'],{material:m.id,disable:true}));bind('#mixundo',async()=>{await api('/api/audio-undo',{material:m.id});state.dirty=false;await refreshMaterial();await audioPage();});commandPanel($('#mixforms'),['audio-mix']);}
