async function splitMergePage(){$('#page').innerHTML=title('Split / Merge / Compilation','Split temporal pentru audio existent; ordine explicită la merge. Ratele diferite cer conversie explicită.')+`<div class="card"><h2>Ordine materiale</h2><div id="mergeorder"></div><button id="addmaterial">Adaugă materialul selectat</button><div class="row">${field('compilation_id','studio-compilation-'+Date.now())}${num('pause_before',0)}${num('pause_between',0)}${num('pause_after',0)}${num('sample_rate',22050,1)}</div><details><summary>Intro/outro/normalizare/visual JSON (contract backend existent)</summary><textarea id="compilationjson">{}</textarea></details><div class="row"><button id="compileplan">Plan compilation</button><button id="compileapply">Create compilation</button></div></div><details open><summary>Toate operațiile backend</summary><div id="deriveforms"></div></details>`;let order=[];function draw(){$('#mergeorder').innerHTML=order.map((m,i)=>`<div class="row">${esc(m)} <button data-up="${i}">↑</button><button data-down="${i}">↓</button><button data-drop="${i}">Remove</button></div>`).join('');for(const name of ['up','down','drop'])$$('[data-'+name+']').forEach(b=>b.onclick=()=>{const i=Number(b.dataset[name]);if(name==='drop')order.splice(i,1);else{const target=i+(name==='up'?-1:1);if(target>=0&&target<order.length)[order[i],order[target]]=[order[target],order[i]];}draw();state.dirty=true;});}bind('#addmaterial',()=>{if(!state.material)throw Error('Alege material.');order.push(state.material.id);draw();state.dirty=true;});async function compile(plan){if(!order.length)throw Error('Adaugă materiale.');const c=JSON.parse($('#compilationjson').value);c.sample_rate=Number($('[name=sample_rate]').value);for(const k of ['pause_before','pause_between','pause_after']){const v=Number($('[name='+k+']').value);if(v>0)c[k]=v;}await submit('media',['compile'],{materials:order,id:$('[name=compilation_id]').value,plan_only:plan},{composition:c});}bind('#compileplan',()=>compile(true));bind('#compileapply',()=>compile(false));commandPanel($('#deriveforms'),['split','merge','compile','compile-video','convert-narration']);trackDirty();}
async function renderPageUI(){if(!needMaterial())return;$('#page').innerHTML=title('Render','Planifică înainte de export. Nicio resinteză sau realiniere implicită.')+`<form id="renderform" class="card"><div class="row">${check('landscape',true)}${check('portrait',false)}${check('custom',false)}${num('width',640,2)}${num('height',360,2)}</div><div class="row">${select('subtitles',['off','classic','highlight','scroll'],'highlight')}${field('title',state.material.titles?.locked?state.material.titles.selected||'':'')}${field('output_root',newDest('render'))}</div><div class="row">${field('resume_run','')}${check('rerender_changed',false)}</div><p>Audio mix activ: ${state.material.audio_mix?.enabled?'DA':'NU'} · stil și profil din material.composition. Thumbnail se exportă separat.</p><div class="row"><button type="button" id="renderplan">Inspect render plan / reuse</button><button type="submit" class="primary">START RENDER</button></div></form><div id="renderplanresult"></div><div id="renderjob"></div>`;trackDirty();function values(){const fd=new FormData($('#renderform')),profiles=['landscape','portrait','custom'].filter(p=>fd.get(p)==='on').join(',');const v={material:state.material.id,profiles,subtitles:fd.get('subtitles'),output_root:fd.get('output_root')};if(profiles.includes('custom')){v.width=Number(fd.get('width'));v.height=Number(fd.get('height'));}if(fd.get('title'))v.title=fd.get('title');if(fd.get('resume_run'))v.resume_run=fd.get('resume_run');v.rerender_changed=fd.get('rerender_changed')==='on';return v;}bind('#renderplan',async()=>{const r=await api('/api/render-plan',values());$('#renderplanresult').innerHTML=info(r);});$('#renderform').onsubmit=safe(async e=>{e.preventDefault();const v=values();const plan=await api('/api/render-plan',v);$('#renderplanresult').innerHTML=info(plan);if(!confirm('Pornești render explicit în destinația aleasă?'))return;const j=await submit('media',['render'],v);state.job=j.id;});}
async function waitJob(id){for(;;){const j=await api('/api/job?id='+id);if(!['running','queued','cancelling'].includes(j.status))return j;await new Promise(r=>setTimeout(r,500));}}
async function jobList(container){const jobs=await api('/api/jobs');container.innerHTML=jobs.length?`<table><thead><tr><th>ID / type</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${esc(j.id.slice(0,8))}<br>${esc(j.type)}</td><td>${badge(j.status)}</td><td>${esc(j.created)}</td><td><button data-inspect="${j.id}">Inspect</button>${['running','queued','cancelling'].includes(j.status)?`<button data-cancel="${j.id}">Cancel</button>`:''}${['failed','cancelled','interrupted'].includes(j.status)?`<button data-resume="${j.id}">Resume</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">Niciun job Studio încă.</p>';$$('[data-inspect]',container).forEach(b=>b.onclick=safe(async()=>{state.job=b.dataset.inspect;await showJob();}));$$('[data-cancel]',container).forEach(b=>b.onclick=safe(async()=>{await api('/api/cancel',{id:b.dataset.cancel});await jobList(container);}));$$('[data-resume]',container).forEach(b=>b.onclick=safe(async()=>{const j=await api('/api/resume',{id:b.dataset.resume});state.job=j.id;await jobList(container);}));}
async function workflowPage(){$('#page').innerHTML=title('Workflow / Batch','Pași locali validați, inputs/outputs și receipts existente. --only păstrează restanțele partial; fără Search/Download ascuns.')+'<div id="workflowform"></div>';commandPanel($('#workflowform'),['workflow','batch']);}
async function jobsPage(){const isLog=state.page==='Logs';$('#page').innerHTML=title(isLog?'Logs':'Jobs / Recovery','Receipts/joburi persistente; restartul verifică PID + identitatea procesului. Încercările incomplete sunt păstrate.')+`<button id="refreshjobs">Refresh</button><div id="joblist"></div><div id="jobdetail"></div>`;await jobList($('#joblist'));bind('#refreshjobs',()=>jobList($('#joblist')));if(state.job)await showJob();}
async function showJob(){if(!state.job)return;const j=await api('/api/job?id='+state.job),el=$('#jobdetail')||$('#renderjob');if(!el)return;el.innerHTML=`<div class="card"><h2>${esc(j.type)} ${badge(j.status)}</h2><p>${esc(j.id)} · ${j.elapsed||0}s · ${esc(j.current_step)}</p>${j.progress?`<progress max="100" value="${j.progress.percent}"></progress><p>${esc(j.progress.scope)}</p>`:''}<div class="row"><button id="copylog">Copy log</button>${['running','queued','cancelling'].includes(j.status)?'<button id="canceljob">Cancel</button>':''}${['failed','interrupted','cancelled'].includes(j.status)?'<button id="resumejob">Resume</button>':''}</div><pre id="logtext">${esc(j.log_tail||'În așteptare…')}</pre>${j.result?`<details open><summary>Result / verification / artifacts</summary>${info(j.result)}${resultLinks(j.result)}</details>`:''}<details><summary>Comandă structurată / timestamps / diagnostic</summary>${info(j)}</details></div>`;bind('#copylog',()=>navigator.clipboard.writeText(j.log_tail||''));bind('#canceljob',async()=>{await api('/api/cancel',{id:j.id});await showJob();});bind('#resumejob',async()=>{const n=await api('/api/resume',{id:j.id});state.job=n.id;await jobsPage();});}
async function verifyPage(){if(!needMaterial())return;const m=state.material;$('#page').innerHTML=title('Verify','Verificări tehnice și provenance separate de acceptanța umană.')+`<div class="statusgrid">${Object.entries(m.review_statuses).map(([k,v])=>badge(k+': '+v)).join('')}</div><div class="row"><button id="verify-material">Validate material / sources / assets</button><button id="verify-alignment">Validate alignment identities</button></div><div id="verifyresult"></div><h2>Audio / video / subtitles / mix</h2><div id="verifyforms"></div>`;bind('#verify-material',async()=>{const j=await submit('studio',['verify-material'],{material:m.id});const r=await waitJob(j.id);$('#verifyresult').innerHTML=info(r.result||r);});bind('#verify-alignment',async()=>{$('#verifyresult').innerHTML=info(await api('/api/ctc?id='+encodeURIComponent(m.id)));});commandPanel($('#verifyforms'),['verify','audio-mix','alignment-review','subtitles']);}
function outputTable(rows){return `<table><thead><tr><th>Path / profile</th><th>Size</th><th>Verify</th><th>Open / hash</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${esc(r.path)}<br>${esc(r.profile)}<small>${new Date(r.modified*1000).toISOString()}</small></td><td>${(r.size/1024/1024).toFixed(2)} MB</td><td>${badge(r.verify_status)}</td><td><a href="${esc(r.url)}" target="_blank" rel="noopener">Open</a> <button data-output="${esc(r.path)}">Preview</button> <button data-hash="${esc(r.path)}">SHA256</button></td></tr>`).join('')}</tbody></table>`;}
async function outputsPage(){const rows=await api('/api/outputs');$('#page').innerHTML=title('Outputs','Video, audio, thumbnails, credits și review reports. .part nu este export final.')+`<button id="outputfolder">Open output folder</button><div id="outputpreview"></div>${outputTable(rows)}`;bind('#outputfolder',()=>api('/api/open-folder',{path:'output'}).then(r=>notice(JSON.stringify(r))));bindOutputButtons();}
function bindOutputButtons(){$$('[data-hash]').forEach(b=>b.onclick=safe(async()=>notice(JSON.stringify(await api('/api/hash?path='+encodeURIComponent(b.dataset.hash))))));$$('[data-output]').forEach(b=>b.onclick=safe(async()=>{const p=b.dataset.output,u='/files?path='+encodeURIComponent(p),el=$('#outputpreview');if(!el){window.open(u);return;}el.innerHTML=/\.(mp4|webm)$/i.test(p)?`<video controls src="${u}"></video>`:/\.(wav|mp3|flac|ogg)$/i.test(p)?`<audio controls src="${u}"></audio>`:/\.(png|jpg|jpeg|webp)$/i.test(p)?`<img style="max-height:500px;max-width:100%" alt="Output" src="${u}">`:`<a href="${u}" target="_blank" rel="noopener">Deschide raport</a>`;}));}
async function settingsPage(){const s=await api('/api/settings');$('#page').innerHTML=title('Settings / Hardware','Configurarea motorului și modelele sunt read-only. Nicio instalare sau descărcare automată.')+`<div class="card"><h2>Preferințe Studio</h2><form id="defaultform"><div class="row">${select('profile',['landscape','portrait','square'],s.defaults.profile||'landscape')}${select('subtitle_preset',['safe','boxed','minimal'],s.defaults.subtitle_preset||'safe')}${select('theme',['dark','light'],state.theme)}<button type="submit">Save UI defaults</button></div></form></div><div class="grid"><div class="card"><h2>CPU / RAM / GPU</h2>${info(s.hardware)}</div><div class="card"><h2>Media defaults</h2>${info(s.media)}</div><div class="card"><h2>Piper defaults</h2>${info(s.tts)}</div></div><p>Output: output/ · cache: work/ · Config per material prin paginile Scene/Subtitles/Audio. Cheia Pexels se configurează în mediul serverului (PEXELS_API_KEY), nu în browser/rapoarte.</p><p class="warn">AI Image: ${esc(s.hardware.ai_image.reason)} AI Video: ${esc(s.hardware.ai_video.reason)}</p><details><summary>Inventar CLI exact, derivat din parser</summary>${info(state.boot.catalog)}</details>`;trackDirty();$('#defaultform').onsubmit=safe(async e=>{e.preventDefault();const fd=new FormData(e.target);await api('/api/defaults',Object.fromEntries(fd));state.theme=fd.get('theme');applyTheme();state.dirty=false;notice('Preferințe Studio salvate. Configurația CLI este păstrată.');});}
async function reviewPage(){if(!needMaterial())return;$('#page').innerHTML=title('Human Review Status')+`<div class="statusgrid">${Object.entries(state.material.review_statuses).map(([k,v])=>badge(k+': '+v)).join('')}</div><p>Doar reviewerul poate confirma audiția și acceptanța editorială. Selecțiile programatice și testele browser nu sunt aprobare umană.</p><div class="row"><button id="reviewctc">CTC Review</button><button id="reviewscenes">Scene Review</button></div><div id="reviewexport"></div>`;bind('#reviewctc',()=>navigate('CTC Review'));bind('#reviewscenes',()=>navigate('Scenes'));commandPanel($('#reviewexport'),['alignment-review','assets review','assets credits']);}
async function renderPage(){const routes={'Dashboard':dashboard,'Materials':materialsPage,'Text / TTS':textPage,'Split Text':splitTextPage,'Alignment':alignmentPage,'CTC Review':ctcPage,'Scenes':scenePage,'Assets':assetsPage,'Library':libraryPage,'Subtitles':subtitlesPage,'Audio Mix':audioPage,'Titles / Thumbnail':titlePage,'Split / Merge':splitMergePage,'Render':renderPageUI,'Workflow':workflowPage,'Jobs':jobsPage,'Logs':jobsPage,'Verify':verifyPage,'Review':reviewPage,'Outputs':outputsPage,'Settings':settingsPage};await routes[state.page]();bindOutputButtons();}
async function reloadBootstrap(){const previous=$('#material').value;state.boot=await api('/api/bootstrap');csrf=state.boot.csrf;$('#material').innerHTML='<option value="">Alege material</option>'+state.boot.materials.map(m=>`<option value="${esc(m.id)}">${esc(m.id)}</option>`).join('');$('#material').value=previous;}
function applyTheme(){document.body.classList.toggle('light',state.theme==='light');localStorage.setItem('rec-theme',state.theme);}
async function poll(){if(polling)return;polling=true;try{const jobs=await api('/api/jobs');const active=jobs.find(j=>['running','queued','cancelling'].includes(j.status));$('#jobbar').textContent=active?`${active.type} · ${active.status} · ${active.id.slice(0,8)} · Jobs / Logs pentru detalii`:'Niciun job activ · CLI: ./tts · ./media';if(state.job){const j=await api('/api/job?id='+state.job);if(active?.id===j.id)$('#jobbar').textContent+=` · ${j.elapsed||0}s · ${j.current_step}`;if(['Jobs','Logs','Render'].includes(state.page))await showJob();if(j.status==='complete' && state.lastCompleted!==j.id){state.lastCompleted=j.id;await refreshMaterial();notice(`Job ${j.id.slice(0,8)} complet. Reîncarcă pagina de lucru pentru datele noi.`);}}}catch(e){$('#connection').textContent='Conexiune întreruptă · restart / refresh';}finally{polling=false;}}
document.addEventListener('keydown',safe(async e=>{if($('dialog[open]')||e.target.closest('input,textarea,select,[contenteditable]')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key===' '){const player=$('main video,main audio');if(player){e.preventDefault();if(player.paused)await player.play();else player.pause();}}if(state.page==='Scenes'){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();if(!allowLeave())return;state.dirty=false;state.scene=(state.scene+(e.key==='ArrowRight'?1:-1)+state.material.scenes.length)%state.material.scenes.length;await scenePage();}if(['a','n'].includes(e.key.toLowerCase())){const status=e.key.toLowerCase()==='a'?'APPROVED':'NEEDS_REVIEW';if(status==='APPROVED'&&!confirm('Confirmi review editorial explicit pentru scena selectată?'))return;await submit('media',['scenes'],{material:state.material.id,scene:state.material.scenes[state.scene].id},{set:{review_status:status}});}}if(state.page==='CTC Review'){if(e.key==='ArrowLeft')$('#ctc-prev')?.click();if(e.key==='ArrowRight')$('#ctc-next')?.click();if(e.key.toLowerCase()==='a')$('[data-decision=ACCEPT]')?.click();if(e.key.toLowerCase()==='n')$('[data-decision=NEEDS_REVIEW]')?.click();}}));
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
async function init(){await reloadBootstrap();$('#project').textContent=state.boot.project;$('#nav').innerHTML=pages.map(p=>`<button class="${p===state.page?'active':''}">${esc(p)}</button>`).join('');$$('#nav button').forEach(b=>b.onclick=safe(()=>navigate(b.textContent)));bind('#material',async()=>{if(!allowLeave()){$('#material').value=state.material?.id||'';return;}state.dirty=false;state.scene=0;state.decisions={};await refreshMaterial();await renderPage();},'change');bind('#theme',()=>{state.theme=state.theme==='dark'?'light':'dark';applyTheme();});applyTheme();$('#pickerroots').innerHTML=['input','samples','materials','assets','output','work/studio'].map(p=>`<button data-root="${p}">${p}</button>`).join('');$$('[data-root]').forEach(b=>b.onclick=safe(()=>listPicker(b.dataset.root)));bind('#pickerclose',()=>$('#picker').close());bind('#upload',async()=>{const f=$('#upload').files[0];if(!f)return;if(f.size>8_000_000)throw Error('Upload limitat la 8 MB; alege un fișier deja în proiect pentru dimensiuni mai mari.');const raw=new Uint8Array(await f.arrayBuffer());let s='';for(let i=0;i<raw.length;i+=8192)s+=String.fromCharCode(...raw.subarray(i,i+8192));const r=await api('/api/upload',{name:f.name,data:btoa(s)});pickerCallback(r.path);$('#picker').close();},'change');await renderPage();setInterval(poll,1200);}
window.addEventListener('DOMContentLoaded',()=>safe(init)(),{once:true});
